   142	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
   143	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
   144	  const mergeBasket = useShopperBasketsMutation('mergeBasket');
   145	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
   146	  const registerModal = useAuthModal(REGISTER_VIEW);
