    79	  intentId: string;
    80	};
    81	
    82	export type UseWishlistAuthDrawerReturn = {
    83	  isOpen: boolean;
    84	  handleDrawerClose: () => void;
    85	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
    86	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
    87	  triggerRef: RefObject<HTMLElement>;
    88	  drawerTitle: string;
    89	  description: string;
    90	  emailValue: string;
    91	  onEmailChange: (val: string) => void;
    92	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
    93	  onSignInWithApple?: () => void;
    94	  onSignInWithGoogle?: () => void;
    95	  isSocialEnabled: boolean;
    96	  /** Whether the passwordless email login flow is available per site config. */
    97	  isPasswordlessEnabled: boolean;
    98	  emailInputRef: RefObject<HTMLInputElement>;
    99	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
   100	  socialError?: string;
   101	  onCreateAccount: () => void;
   102	  isOtpAuthOpen: boolean;
   103	  onOtpAuthClose: () => void;
   104	  form: UseFormReturn<FieldValues>;
   105	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
   106	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
   107	  registerModal: ReturnType<typeof useAuthModal>;
   108	};
   109	
   110	/**
   111	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
   112	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
   113	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
   114	 *
   115	 * @returns All state and event handlers needed to render and drive the auth gate UI.
   116	 */
   117	export const useWishlistAuthDrawer = ({
   118	  onAuthSuccess,
   119	  intentId,
   120	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
   121	  const { formatMessage } = useIntl();
   122	  const { t } = useUiCopy();
   123	  const { data: customer } = useCurrentCustomer();
   124	  const { isRegistered } = useCustomerType();
   125	  const { isOpen, onOpen, onClose } = useDisclosure();
   126	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
   127	  const [emailValue, setEmailValue] = useState('');
   128	  const [socialError, setSocialError] = useState<string | undefined>();
   129	  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
   130	  const form = useForm();
   131	  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
   132	  const emailInputRef = useRef<HTMLInputElement>(null);
   133	
   134	  // AC10 focus-return: capture the clicked/focused trigger element at click time.
   135	  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
   136	  // guaranteed for all consumers. document.activeElement at onClick time is always the
   137	  // element that was interacted with, regardless of how the child is implemented.
   138	  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
   139	  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);
   140	
   141	  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
   142	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
   143	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
   144	  const mergeBasket = useShopperBasketsMutation('mergeBasket');
   145	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
   146	  const registerModal = useAuthModal(REGISTER_VIEW);
   147	  const { locale } = useMultiSite();
   148	
   149	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
   150	  const loginConfig = (getConfig().app.login || {}) as any;
   151	  const passwordlessConfig = loginConfig.passwordless;
   152	  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
   153	  const isSocialEnabled = !!loginConfig.social?.enabled;
   154	  const idps: string[] = loginConfig.social?.idps ?? [];
   155	  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
   156	  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;
   157	
   158	  // Move focus to the email input once the drawer's enter animation completes.
   159	  useEffect(() => {
   160	    if (!isOpen) return;
   161	    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
   162	    return () => clearTimeout(timer);
   163	  }, [isOpen]);
   164	
   165	  // When the customer transitions to registered while the drawer (or OTP modal) is open,
   166	  // close everything, fire the deferred action, and merge the guest basket the shopper was
   167	  // just signed out of (passwordless login only — see the merge call's own comment below).
   168	  useEffect(() => {
   169	    if (isRegistered && (isOpen || isOtpAuthOpen)) {
   170	      onClose();
   171	      setIsOtpAuthOpen(false);
   172	      onAuthSuccess?.();
   173	
   174	      // Passwordless sign-in switches the SDK session to the registered customer without
   175	      // merging the guest basket — left unmerged, the shopper's guest-basket items are
   176	      // orphaned, not just miscounted. This mirrors base `use-auth-modal.js`'s own
   177	      // `handleMergeBasket`, called from that file's structural equivalent of this effect
   178	      // (its own `useEffect(..., [isRegistered])`) rather than from `handleOtpVerification` —
   179	      // `isRegistered` (from `useCustomerType()`) is the signal that customer-dependent state
   180	      // has actually caught up with the session switch, not just that the login mutation
   181	      // resolved, which is presumably why base waits for it here too. The social-IDP route
   182	      // needs no merge added here — it redirects through base `social-login-redirect`, which
   183	      // already merges on its own. Create-account never reaches this branch — a new customer
   184	      // has no prior basket to merge, and `handleTriggerClick` only opens this drawer for a
   185	      // guest in the first place, so every path reaching this effect already started as a
   186	      // guest session (unlike base, no `prevAuthType === 'guest'` check is needed to establish
   187	      // that).
   188	      //
   189	      // Deliberately does not gate on `hasBasketItem` the way base does: that would add a new
   190	      // basket-loading dependency to a hook that has never needed one, and the failure mode of
   191	      // getting its timing wrong (a merge silently skipped when it shouldn't be) is worse than
   192	      // the cost of one occasional harmless merge call against an empty basket.
   193	      //
   194	      // productItemMergeMode is 'sum_quantities', not the SDK's 'higher_quantity' default —
   195	      // deliberate, not a copy of base's call. This changes the result of every merge, not
   196	      // just over-the-cap ones: a guest who adds one unit of an item, then signs into an
   197	      // account that already had one unit of that same item, gets two units after merge, not
   198	      // one. No AC describes this, so a future reader/tester with no memory of this decision
   199	      // needs it stated plainly: two units is intended.
   200	      mergeBasket.mutate({
   201	        headers: {
   202	          // Not required since the request has no body, but CommerceAPI throws a
   203	          // '419 - Unsupported Media Type' error if this header is removed.
   204	          'Content-Type': 'application/json',
   205	        },
   206	        parameters: {
   207	          createDestinationBasket: true,
   208	          productItemMergeMode: 'sum_quantities',
   209	        },
   210	      });
   211	    }
   212	  }, [isRegistered]);
   213	
   214	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
   215	  // On mount, if the shopper is already registered and a pending intent was stored before the
   216	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
   217	  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
   218	  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
   219	  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
   220	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
   221	  // intentId are intentionally omitted because the intent fires at most once per redirect
   222	  // cycle, and the flag is cleared before any re-render that could change either.
   223	  useEffect(() => {
   224	    if (!isRegistered) return;
   225	    const pending = readPendingWishlistIntent();
   226	    if (!pending || pending.intentId !== intentId) return;
   227	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
   228	    onAuthSuccess?.();
   229	    // eslint-disable-next-line react-hooks/exhaustive-deps
   230	  }, [isRegistered]);
   231	
   232	  const handleDrawerClose = () => {
   233	    onClose();
   234	    form.reset();
   235	    setEmailValue('');
   236	  };
   237	
   238	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
   239	    // e.currentTarget is always the element the handler is attached to — reliable across
   240	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
   241	    triggerRef.current = e.currentTarget;
   242	    if (customer?.isRegistered) {
   243	      onAuthSuccess?.();
   244	    } else {
   245	      onOpen();
   246	    }
   247	  };
   248	
   249	  const handlePasswordlessLogin = async (email: string) => {
   250	    try {
   251	      const redirectPath = window.location.pathname + (window.location.search ?? '');
   252	      await authorizePasswordlessLogin.mutateAsync({
   253	        userid: email,
   254	        mode: passwordlessConfig?.mode,
   255	        locale: locale.id,
   256	        ...(callbackURL && {
   257	          callbackURI: (() => {
   258	            const url = new URL(callbackURL);
   259	            url.searchParams.set('redirectUrl', redirectPath);
   260	            return url.toString();
   261	          })(),
   262	        }),
   263	      });
   264	      return { success: true };
   265	    } catch (error) {
   266	      return {
   267	        success: false,
   268	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
   269	      };
   270	    }
   271	  };
   272	
   273	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
   274	    try {
   275	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
   276	      return { success: true };
   277	    } catch (e) {
   278	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
   279	      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
   280	    }
   281	  };
   282	
   283	  const onSendCode = async () => {
   284	    if (!isPasswordlessEnabled) return;
   285	    const result = await handlePasswordlessLogin(emailValue);
   286	    if (result.success) {
   287	      onClose();
   288	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
   289	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
   290	    }
   291	    return result;
   292	  };
   293	
   294	  const onSignInWithApple =
   295	    isSocialEnabled && idps.includes('apple')
   296	      ? async () => {
   297	          setSocialError(undefined);
   298	          try {
   299	            setSessionJSONItem('returnToPage', window.location.pathname);
   300	            // Persist the wishlist intent before the redirect — the page reloads after social
   301	            // auth completes and onAuthSuccess would otherwise never fire.
   302	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
   303	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
   304	            await authorizeIDP.mutateAsync({
   305	              hint: 'apple',
   306	              // Social IDP redirects are browser-only — window.location.origin is always available
   307	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
   308	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
   309	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
   310	            });
   311	          } catch {
   312	            // mutateAsync rejected before the browser navigated away (e.g. a network/config
   313	            // error) — no redirect happened, so the intent just stored is already stale.
   314	            // Clear it so it can't misfire a later, unrelated registration in this tab.
   315	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
   316	            setSocialError(formatMessage(API_ERROR_MESSAGE));
   317	          }
   318	        }
   319	      : undefined;
   320	
   321	  const onSignInWithGoogle =
   322	    isSocialEnabled && idps.includes('google')
   323	      ? async () => {
   324	          setSocialError(undefined);
   325	          try {
   326	            setSessionJSONItem('returnToPage', window.location.pathname);
   327	            // Persist the wishlist intent before the redirect — same reason as Apple above.
   328	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
   329	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
   330	            await authorizeIDP.mutateAsync({
   331	              hint: 'google',
   332	              // Social IDP redirects are browser-only — window.location.origin is always available
   333	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
   334	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
   335	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
   336	            });
   337	          } catch {
   338	            // Same reasoning as Apple's catch above — no redirect occurred, so clear the
   339	            // just-stored intent rather than leaving it to misfire later.
   340	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
   341	            setSocialError(formatMessage(API_ERROR_MESSAGE));
   342	          }
   343	        }
   344	      : undefined;
   345	
   346	  const onCreateAccount = () => {
   347	    handleDrawerClose();
   348	    registerModal.onOpen();
   349	  };
   350	
   351	  return {
   352	    isOpen,
   353	    handleDrawerClose,
   354	    handleTriggerClick,
   355	    triggerRef,
   356	    drawerTitle: formatMessage(messages.drawerTitle),
   357	    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
   358	    emailValue,
   359	    onEmailChange: setEmailValue,
   360	    onSendCode,
   361	    onSignInWithApple,
   362	    onSignInWithGoogle,
   363	    isSocialEnabled,
   364	    isPasswordlessEnabled,
   365	    emailInputRef,
   366	    socialError,
   367	    onCreateAccount,
   368	    isOtpAuthOpen,
   369	    onOtpAuthClose: () => setIsOtpAuthOpen(false),
   370	    form,
   371	    handlePasswordlessLogin,
   372	    handleOtpVerification,
   373	    registerModal,
   374	  };
   375	};

